code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            # Detect a four-cell diamond: center is 0; four diagonal-neighbor tips are 2.
            for cr in range(max(1, r-1), min(h-1, r+2)):
                for cc in range(max(1, c-1), min(w-1, c+2)):
                    cells = {(cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)}
                    if all(grid[rr][cx] == 2 for rr,cx in cells):
                        centers.append((cr,cc))
                        seen.update(cells)
    # Bridge aligned neighboring diamonds with color 1.
    for i, (r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r == rr:
                for x in range(min(c,cc)+2, max(c,cc)-1):
                    if out[r][x] == 0: out[r][x] = 1
            elif c == cc:
                for y in range(min(r,rr)+2, max(r,rr)-1):
                    if out[y][c] == 0: out[y][c] = 1
    return out
'''
